namespace beast = webcpp::beast;  // from <webcpp/beast.hpp>
namespace http = beast::http;     // from <webcpp/beast/http.hpp>
// from <boost/asio.hpp>
namespace ssl = webcpp::asio::ssl;  // from <boost/asio/ssl.hpp>
using webcpp::asio::ip::tcp;        // from <boost/asio/ip/tcp.hpp>

// Performs an HTTP GET and prints the response
namespace {
// The process entry point retains the standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int application_main(int argc, char** argv) {
    {
        // Check command line arguments.
        if (argc != 4 && argc != 5) {
            std::cerr << "Usage: http-client-sync-ssl <host> <port> <target> [<HTTP version: 1.0 "
                         "or 1.1(default)>]\n"
                      << "Example:\n"
                      << "    http-client-sync-ssl www.example.com 443 /\n"
                      << "    http-client-sync-ssl www.example.com 443 / 1.0\n";
            return EXIT_FAILURE;
        }
        const auto* const host = argv[1];
        const auto* const port = argv[2];
        const auto* const target = argv[3];
        int const version = argc == 5 && (std::strcmp("1.0", argv[4]) == 0) ? 10 : 11;

        // The io_context is required for all I/O
        webcpp::asio::io_context ioc;

        // The SSL context is required, and holds certificates
        ssl::context ctx(ssl::context::tls_client);

        // This holds the root certificate used for verification
        // Browser trust store owns TLS authorities.

        // Verify the remote server's certificate
        {
            boost::system::error_code verify_error;
            ctx.set_verify_mode(ssl::verify_peer, verify_error);
            if (verify_error) {
                webcpp_fixture::fail_stop();
            }
        }

        // These objects perform our I/O
        webcpp::asio::ip::tcp::resolver resolver(ioc);
        beast::ssl_stream<beast::tcp_stream> stream(ioc, ctx);

        // Set SNI Hostname (many hosts need this to handshake successfully)
        beast::set_server_name(stream, host).value();

        // Set the expected hostname in the peer certificate for verification
        stream.set_verify_callback(ssl::host_name_verification(host));

        // Look up the domain name
        auto const results = webcpp_fixture::resolve(resolver, host, port);

        // Make the connection on the IP address we get from a lookup
        beast::get_lowest_layer(stream).connect(results);

        // Perform the SSL handshake
        stream.handshake(ssl::stream_base::client);

        // Set up an HTTP GET request message
        http::request<http::string_body> req{http::verb::get, target, version};
        req.set(http::field::host, host);

        // Send the HTTP request to the remote host
        http::write(stream, req);

        // This buffer is used for reading and must be persisted
        beast::flat_buffer buffer;

        // Declare a container to hold the response
        http::response<http::dynamic_body> res;

        // Receive the HTTP response
        http::read(stream, buffer, res);

        // Write the message to standard out
        std::cout << res << '\n';

        // Gracefully close the stream
        beast::error_code ec;
        stream.shutdown(ec);

        // ssl::error::stream_truncated, also known as an SSL "short read",
        // indicates the peer closed the connection without performing the
        // required closing handshake (for example, Google does this to
        // improve performance). Generally this can be a security issue,
        // but if your communication protocol is self-terminated (as
        // it is with both HTTP and WebSocket) then you may simply
        // ignore the lack of close_notify.
        //
        // https://github.com/boostorg/beast/issues/38
        //
        // https://security.stackexchange.com/questions/91435/how-to-handle-a-malicious-ssl-tls-shutdown
        //
        // When a short read would cut off the end of an HTTP message,
        // Beast returns the error beast::http::error::partial_message.
        // Therefore, if we see a short read here, it has occurred
        // after the message has been completed, so it is safe to ignore it.

        if (static_cast<bool>(ec)) {
            webcpp_fixture::fail_stop();
        }
    }
    return EXIT_SUCCESS;
}

}  // namespace

#include <emscripten/val.h>
#include <sstream>
#include <vector>

int main() {
    const auto port = emscripten::val::global("beastSecurePort").as<std::string>();
    if (setenv("WEBCPP_BEAST_FIXTURE_HOST", "localhost", 1) != 0) {
        return 1;
    }
    if (setenv("WEBCPP_BEAST_FIXTURE_PORT", port.c_str(), 1) != 0) {
        return 1;
    }
    {
        std::vector<std::string> storage{"http-client-sync-ssl", "localhost", port, "/http"};
        std::vector<char*> arguments;
        arguments.reserve(storage.size());
        for (auto& value : storage) {
            arguments.push_back(value.data());
        }
        // This mutable object is passed through the upstream asynchronous or stream interface.
        // NOLINTNEXTLINE(misc-const-correctness)
        std::ostringstream output;
        auto* original = std::cout.rdbuf(output.rdbuf());
        const auto result = application_main(static_cast<int>(arguments.size()), arguments.data());
        std::cout.rdbuf(original);
        std::cout << output.str();
        if (result != 0 || output.str().find("fetch body") == std::string::npos) {
            return 1;
        }
    }
    std::cout << "application http-client-sync-ssl: passed\n";
    return 0;
}
